    [Fact]
    public async Task ValidationErrorIsNotRetriedAndCarriesFields()
    {
        const string Body = "{\"type\":\"error\",\"error\":{\"type\":\"invalid_request_error\",\"message\":\"Check the fields.\",\"code\":\"validation_failed\","
            + "\"fields\":[{\"path\":\"bin\",\"code\":\"invalid_format\",\"message\":\"12 digits\"}],\"future\":{\"a\":1}},\"request_id\":\"req_1\"}";
        var handler = new StubHandler().Json(Body, 400, ("x-request-id", "req_header"));
        using var client = Sdk.Client(handler);
        var error = await Assert.ThrowsAsync<TungoInvalidRequestException>(() => client.Companies.GetAsync());
        Assert.Single(handler.Requests);
        Assert.Equal(400, error.StatusCode);
        Assert.Equal("invalid_request_error", error.Type);
        Assert.Equal("validation_failed", error.Code);
        Assert.Equal("req_1", error.RequestId);
        Assert.Equal("req_header", error.Headers["X-Request-Id"][0]);
        Assert.Equal(Body, error.Body);
        var field = Assert.Single(error.Fields);
        Assert.Equal("bin", field.Path);
        Assert.Equal("12 digits", field.Message);
        Assert.Equal(1, error.Extra["future"].GetProperty("a").GetInt32());
        Assert.Equal("Check the fields.", error.Detail?.Message);
        Assert.Contains("req_1", error.Message, StringComparison.Ordinal);
        Assert.IsAssignableFrom<TungoApiException>(error);
        Assert.IsAssignableFrom<TungoException>(error);
    }

    [Fact]
