        {
            (401, "authentication_error", typeof(TungoAuthenticationException)),
            (402, "payment_required_error", typeof(TungoPaymentRequiredException)),
            (403, "permission_error", typeof(TungoPermissionException)),
            (404, "not_found_error", typeof(TungoNotFoundException)),
            (409, "conflict_error", typeof(TungoConflictException)),
            (410, "gone_error", typeof(TungoGoneException)),
            (429, "limit_error", typeof(TungoLimitException)),
            (400, "brand_new_error", typeof(TungoInvalidRequestException)),
        };
        foreach (var (status, type, expected) in cases)
        {
            var handler = new StubHandler().Json(Sdk.ErrorJson(type, "m", "\"permission\":\"chat.write\""), status);
            using var client = Sdk.Client(handler, options => options.MaxRetries = 0);
            var error = await Assert.ThrowsAnyAsync<TungoApiException>(() => client.Companies.GetAsync());
            Assert.IsType(expected, error);
            Assert.Equal(type, error.Type);
            Assert.Equal("chat.write", error.Detail?.Permission);
            Assert.Equal("chat.write", error.Extra["permission"].GetString());
        }
    }

