    [Fact]
    public void InjectedHttpClientWithATimeoutShorterThanTheSdksIsRefused()
    {
        TungoClient Create(HttpClient http, Action<TungoClientOptions>? configure = null)
        {
            var options = new TungoClientOptions { ApiKey = Sdk.ApiKey, BaseUrl = new Uri("https://api.test/"), HttpClient = http };
            configure?.Invoke(options);
            return new TungoClient(options);
        }

        // The default of HttpClient is 100 s: it would end a 600 s chat turn.
        using var byDefault = new HttpClient(new StubHandler());
        var error = Assert.Throws<TungoConfigurationException>(() => Create(byDefault));
        Assert.Contains("Timeout.InfiniteTimeSpan", error.Message, StringComparison.Ordinal);
        Assert.Contains("100 s", error.Message, StringComparison.Ordinal);
        Assert.Contains("600 s", error.Message, StringComparison.Ordinal);

        using var unlimited = new HttpClient(new StubHandler()) { Timeout = Timeout.InfiniteTimeSpan };
        Create(unlimited).Dispose();
        using var longEnough = new HttpClient(new StubHandler()) { Timeout = TimeSpan.FromSeconds(600) };
        Create(longEnough).Dispose();

        // Lowering the SDK's own limits to fit the client is accepted; an unlimited SDK timeout over a limited client is not.
        Create(byDefault, options => options.ChatTimeout = TimeSpan.FromSeconds(90)).Dispose();
        Assert.Throws<TungoConfigurationException>(() => Create(longEnough, options => options.ChatTimeout = Timeout.InfiniteTimeSpan));
    }

