    {
        // What an HttpClient that follows redirects hands back: the response of the request it was redirected to.
        static Func<RecordedRequest, CancellationToken, Task<HttpResponseMessage>> AnsweredBy(string uri, string contentType, string body)
        {
            return (_, _) =>
            {
                var response = StubHandler.Response(200, body, contentType);
                response.RequestMessage = new HttpRequestMessage(HttpMethod.Get, uri);
                return Task.FromResult(response);
            };
        }

        var handler = new StubHandler()
            .Then(AnsweredBy("https://evil.test/v1/companies/co_1", "application/json", Sdk.CompanyJson))
            .Then(AnsweredBy("http://api.test/v1/companies/co_1", "application/json", Sdk.CompanyJson))
            .Then(AnsweredBy("https://api.test:8443/v1/companies/co_1", "application/json", Sdk.CompanyJson))
            .Then(AnsweredBy("https://evil.test/v1/companies/co_1/chat", "text/event-stream", "event: done\ndata: {\"type\":\"done\"}\n\n"))
            .Then(AnsweredBy("https://API.test/v1/moved", "application/json", Sdk.CompanyJson));
        using var client = Sdk.Client(handler);

        var error = await Assert.ThrowsAsync<TungoConfigurationException>(() => client.Companies.GetAsync());
        Assert.Contains("https://evil.test", error.Message, StringComparison.Ordinal);
        Assert.Contains("AllowAutoRedirect", error.Message, StringComparison.Ordinal);
        Assert.DoesNotContain(Sdk.ApiKey, error.Message, StringComparison.Ordinal);
        await Assert.ThrowsAsync<TungoConfigurationException>(() => client.Companies.GetAsync());
        await Assert.ThrowsAsync<TungoConfigurationException>(() => client.Companies.GetAsync());
        await Assert.ThrowsAsync<TungoConfigurationException>(async () =>
        {
            await foreach (var chatEvent in client.Chat.CreateStreamAsync(new ChatMessageRequest { Message = "hi" }))
            {
                Assert.Fail("a response from another origin must not be delivered: " + chatEvent);
            }
        });

        // Never retried, and the same origin (whatever the path) is fine.
        Assert.Equal(4, handler.Requests.Count);
        Assert.Equal("co_1", (await client.Companies.GetAsync()).Id);
    }

    [Fact]
    public async Task EmptyResponseBodyIsAccepted()
    {
        var handler = new StubHandler().Then((_, _) => Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.NoContent)));
        using var client = Sdk.Client(handler);
        await client.Webhooks.DeleteEndpointAsync("ep_1");
        var request = Assert.Single(handler.Requests);
        Assert.Equal("DELETE", request.Method);
        Assert.Equal("https://api.test/v1/workspaces/ws_1/webhooks/endpoints/ep_1", request.Uri.AbsoluteUri);
    }

    [Fact]
    public async Task PagesAreTypedAndLinked()
    {
        var handler = new StubHandler()
            .Json(Sdk.DialogsJson("c2", "d1", "d2"), 200, ("x-request-id", "req_p1"))
            .Json(Sdk.DialogsJson(null, "d3"));
        using var client = Sdk.Client(handler);
        var page = await client.Chat.ListAsync(new ChatListParams { Limit = 2 });
        Assert.Equal(new[] { "d1", "d2" }, page.Data.Select(dialog => dialog.Id));
        Assert.Equal("c2", page.NextCursor);
        Assert.True(page.HasNextPage);
        Assert.Equal("c2", page.Body.NextCursor);
        Assert.Equal("req_p1", page.Response.RequestId);

        var next = await page.GetNextPageAsync();
        Assert.NotNull(next);
        Assert.Equal("d3", Assert.Single(next.Data).Id);
        Assert.False(next.HasNextPage);
        Assert.Null(await next.GetNextPageAsync());
        Assert.Equal("https://api.test/v1/companies/co_1/chat?cursor=c2&limit=2", handler.Requests[1].Uri.AbsoluteUri);
    }

    [Fact]
    public async Task AutoPaginationWalksEveryPageLazily()
    {
        var handler = new StubHandler()
            .Json(Sdk.DialogsJson("c2", "d1", "d2"))
            .Json(Sdk.DialogsJson("c3"))
            .Json(Sdk.DialogsJson(string.Empty, "d3"));
        using var client = Sdk.Client(handler);
        var ids = new List<string>();
        await foreach (var dialog in client.Chat.ListAllAsync())
        {
            ids.Add(dialog.Id);
            if (ids.Count == 1)
            {
                // The second page is not requested before the first one is consumed.
                Assert.Single(handler.Requests);
            }
        }

        Assert.Equal(new[] { "d1", "d2", "d3" }, ids);
        Assert.Equal(3, handler.Requests.Count);
    }

    [Fact]
    public async Task AutoPaginationStopsOnEarlyBreakAndCancellation()
    {
        var handler = new StubHandler().Json(Sdk.DialogsJson("c2", "d1", "d2")).Json(Sdk.DialogsJson("c2", "d1", "d2"));
        using var client = Sdk.Client(handler);
        await foreach (var dialog in client.Chat.ListAllAsync())
        {
            Assert.Equal("d1", dialog.Id);
            break;
        }

        Assert.Single(handler.Requests);

        using var cancellation = new CancellationTokenSource();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(async () =>
        {
            await foreach (var dialog in client.Chat.ListAllAsync().WithCancellation(cancellation.Token))
            {
                await cancellation.CancelAsync();
            }
        });
        Assert.Equal(2, handler.Requests.Count);
    }

    [Fact]
    public async Task RepeatedCursorStopsAutoPagination()
    {
        var handler = new StubHandler().Json(Sdk.DialogsJson("c2", "d1")).Json(Sdk.DialogsJson("c2", "d2"));
        using var client = Sdk.Client(handler);
        var ids = new List<string>();
        await Assert.ThrowsAsync<TungoDecodeException>(async () =>
        {
            await foreach (var dialog in client.Chat.ListAllAsync())
            {
                ids.Add(dialog.Id);
            }
        });
        Assert.Equal(2, handler.Requests.Count);
        Assert.Equal(new[] { "d1", "d2" }, ids);
    }

    [Fact]
    public async Task CursorCycleStopsAutoPagination()
    {
        // c1 -> c2 -> c1: a cursor seen two pages ago comes back.
        var handler = new StubHandler()
            .Json(Sdk.DialogsJson("c1", "d1"))
            .Json(Sdk.DialogsJson("c2", "d2"))
            .Json(Sdk.DialogsJson("c1", "d3"))
            .Json(Sdk.DialogsJson("c2", "d4"));
        using var client = Sdk.Client(handler);
        var ids = new List<string>();
        var error = await Assert.ThrowsAsync<TungoDecodeException>(async () =>
        {
            await foreach (var dialog in client.Chat.ListAllAsync())
            {
                ids.Add(dialog.Id);
            }
        });
        Assert.Contains("already requested", error.Message, StringComparison.Ordinal);
        Assert.Equal(3, handler.Requests.Count);
        Assert.Equal(new[] { "d1", "d2", "d3" }, ids);
    }

    [Fact]
    public async Task AskSendsOneNonStreamingTurn()
    {
        var handler = new StubHandler().Json(Sdk.TurnJson);
        using var client = Sdk.Client(handler);
        var turn = await client.AskAsync("How much VAT?", dialogId: "d7");
