    [Fact]
    public async Task WaitForRunPollsUntilAFinalState()
    {
        var handler = new StubHandler()
            .Json(Sdk.RunJson("queued"))
            .Json(Sdk.RunJson("running"))
            .Json(Sdk.RunJson("state_from_the_future"))
            .Json(Sdk.RunJson("done"));
        var delays = new List<TimeSpan>();
        using var client = Sdk.Client(handler, delays: delays);
        var run = await client.WaitForRunAsync("run_1");
        Assert.Equal("done", run.State.Value);
        Assert.Equal(4, handler.Requests.Count);
        Assert.Equal(new[] { TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(1.5), TimeSpan.FromSeconds(2.25) }, delays);
    }

    [Fact]
    public async Task WaitGivesUpAtTheDeadline()
    {
        var handler = new StubHandler();
        for (var i = 0; i < 20; i++)
        {
            handler.Json(Sdk.BatchJson(running: true));
        }

        var delays = new List<TimeSpan>();
        using var client = Sdk.Client(handler, delays: delays);
        var wait = new TungoWaitOptions { Timeout = TimeSpan.FromSeconds(10), PollInterval = TimeSpan.FromSeconds(2), MaxPollInterval = TimeSpan.FromSeconds(4) };
        var error = await Assert.ThrowsAsync<TungoTimeoutException>(() => client.WaitForBatchAsync("bt_1", wait));
        Assert.Contains("bt_1", error.Message, StringComparison.Ordinal);
        Assert.Equal(new[] { 2.0, 3.0, 4.0, 1.0 }, delays.Select(delay => Math.Round(delay.TotalSeconds, 1)));
        Assert.Equal(5, handler.Requests.Count);
        await Assert.ThrowsAsync<TungoValidationException>(() => client.WaitForBatchAsync("bt_1", new TungoWaitOptions { Timeout = TimeSpan.Zero }));
    }

    [Fact]
    public async Task WaitForBatchReturnsWhenTheBatchStops()
    {
        var handler = new StubHandler().Json(Sdk.BatchJson(running: true)).Json(Sdk.BatchJson(running: false));
        using var client = Sdk.Client(handler);
        var batch = await client.WaitForBatchAsync("bt_1");
        Assert.False(batch.Running);
        Assert.Equal("https://api.test/v1/companies/co_1/batch/bt_1", handler.Requests[0].Uri.AbsoluteUri);
    }

    [Fact]
    public async Task RunScenarioAndWaitStartsOnceThenPolls()
    {
        var handler = new StubHandler()
            .Json(Sdk.RunJson("queued", detail: false))
            .Json(Sdk.RunJson("running"))
            .Json(Sdk.RunJson("error"));
        using var client = Sdk.Client(handler);
        var run = await client.RunScenarioAndWaitAsync("sc_1", options: new RequestOptions { IdempotencyKey = "start-1" });
        Assert.Equal("error", run.State.Value);
        Assert.Equal(new[] { "POST", "GET", "GET" }, handler.Requests.Select(request => request.Method));
        Assert.Equal("start-1", handler.Requests[0].Header("Idempotency-Key"));
        Assert.Null(handler.Requests[1].Header("Idempotency-Key"));
        Assert.Equal("https://api.test/v1/companies/co_1/automations/runs/run_1", handler.Requests[1].Uri.AbsoluteUri);
    }

    [Fact]
    public async Task PatchSendsExplicitNullOnlyWhenAsked()
    {
        var handler = new StubHandler()
            .Json(Sdk.ErrorJson("not_found_error", "none"), 404)
            .Json(Sdk.ErrorJson("not_found_error", "none"), 404);
        using var client = Sdk.Client(handler);
        await Assert.ThrowsAsync<TungoNotFoundException>(
            () => client.Webhooks.UpdateEndpointAsync("ep_1", new WebhookEndpointPatch { Description = "Orders", EventTypes = null }));
        await Assert.ThrowsAsync<TungoNotFoundException>(
            () => client.Webhooks.UpdateEndpointAsync("ep_1", new WebhookEndpointPatch { Enabled = false, Channels = new[] { "scn_1" } }));
        Assert.Equal("PATCH", handler.Requests[0].Method);
        Assert.Equal("{\"description\":\"Orders\",\"event_types\":null}", handler.Requests[0].Text);
        Assert.Equal("{\"channels\":[\"scn_1\"],\"enabled\":false}", handler.Requests[1].Text);
    }
